#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

#ifdef _OPENMP
# include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initial lower-triangular matrix construction. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	Ai[j] = 0;
      }
      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T.  */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Use local restrict-qualified pointers for clearer aliasing
     information and better vectorization opportunities. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T.
   *
   * Original code:
   *   B[r][s] = 0;
   *   for t
   *     B[r][s] += A[r][t] * A[s][t];
   *
   * Reorganized as:
   *   for r,s: sum over t and write B[r][s] once.
   *
   * For each (r,s), the accumulation order over t (0..n-1) is
   * preserved, so floating-point semantics are unchanged while
   * improving cache locality (A rows and B rows are traversed
   * in row-major order). Each B[r][s] is independent, allowing
   * safe parallelization over r and s.
   */
#ifdef _OPENMP
#pragma omp parallel for collapse(2) schedule(static)
#endif
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      {
	DATA_TYPE sum = (DATA_TYPE)0;
	/* Inner loop is a simple dot product; compilers can
	   readily vectorize this. */
	for (t = 0; t < n; ++t)
	  sum += A_[r][t] * A_[s][t];
	B_[r][s] = sum;
      }

  /* Copy B back into A. The whole matrix is written, so no need
     to preserve previous A values. */
#ifdef _OPENMP
#pragma omp parallel for collapse(2) schedule(static)
#endif
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A_[r][s] = B_[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
    if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Create a restrict-qualified VLA pointer to make aliasing explicit
     and improve the compiler's ability to optimize memory accesses. */
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     DATA_TYPE *restrict Ai = A_[i];

     /* Off-diagonal elements: j < i.
      *
      * Original computation:
      *   for k = 0..j-1:
      *     A[i][j] -= A[i][k] * A[j][k];
      *   A[i][j] /= A[j][j];
      *
      * We accumulate into a local scalar 'sum' initialized from
      * Ai[j]. The sequence of floating-point operations (subtractions
      * over k in increasing order) is identical to repeatedly
      * updating A[i][j] in place, so numerical semantics are
      * preserved while reducing memory traffic.
      */
     for (j = 0; j < i; j++) {
        DATA_TYPE *restrict Aj = A_[j];
        DATA_TYPE sum = Ai[j];

        for (k = 0; k < j; k++) {
           sum -= Ai[k] * Aj[k];
        }

        Ai[j] = sum / Aj[j];
     }

     /* Diagonal element: i == j.
      *
      * Original computation:
      *   for k = 0..i-1:
      *     A[i][i] -= A[i][k] * A[i][k];
      *   A[i][i] = sqrt(A[i][i]);
      *
      * Same idea: use a local accumulator 'sum_diag' initialized
      * from Ai[i], then write back once. Order of operations over k
      * is unchanged.
      */
     DATA_TYPE sum_diag = Ai[i];
     for (k = 0; k < i; k++) {
        DATA_TYPE aik = Ai[k];
        sum_diag -= aik * aik;
     }
     Ai[i] = SQRT_FUN(sum_diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
