#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>   /* Added: optional OpenMP support for parallelism/vectorization */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"


/* Tunable parameters for the optimized kernels.
 *
 * They are intentionally simple integer constants so they can easily be
 * adjusted or overridden at compile time (e.g., with -D).
 */
#ifndef CHOLESKY_INIT_OMP_SCHEDULE
#define CHOLESKY_INIT_OMP_SCHEDULE static
#endif


/* Array initialization.
 *
 * Logical steps:
 *   1. Build a lower-triangular matrix A with simple deterministic entries.
 *   2. Form A := A * A^T so that A becomes symmetric positive semi-definite.
 *
 * Step 2 is implemented as a cache-friendly, symmetric matrix product:
 *   B[r][s] = sum_t A[r][t] * A[s][t]
 * for s <= r, and we mirror to the upper triangle (B[s][r] = B[r][s]).
 *
 * We use a local accumulation variable "sum" for better vectorization, and
 * an OpenMP "simd" directive to encourage SIMDization of the inner loops.
 * The outer loop over r can be parallelized safely because each iteration
 * writes to a disjoint set of B elements.
 */
static
void init_array(int n,
                DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initial lower-triangular matrix. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
        A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++)
        A[i][j] = 0;
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /*
   * Compute only the lower triangle of B and mirror it to the upper
   * triangle. This cuts the number of multiplications roughly in half,
   * and improves cache locality by working with contiguous rows.
   *
   * The OpenMP "parallel for" is optional: if compiled without -fopenmp,
   * these pragmas are ignored by the compiler. With OpenMP enabled, the
   * outer loop over rows is distributed across threads.
   */
#pragma omp parallel for schedule(CHOLESKY_INIT_OMP_SCHEDULE) private(s,t) if (n > 64)
  for (r = 0; r < n; ++r)
    {
      for (s = 0; s <= r; ++s)
        {
          DATA_TYPE sum = (DATA_TYPE)0;
          /* Encourage SIMD on the t-loop; the mathematical expression is
           * identical to the original triple loop, but the accumulation
           * order differs slightly in floating-point arithmetic. */
#pragma omp simd reduction(+:sum)
          for (t = 0; t < n; ++t)
            {
              sum += A[r][t] * A[s][t];
            }

          (POLYBENCH_ARRAY(B))[r][s] = sum;
          (POLYBENCH_ARRAY(B))[s][r] = sum;
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * This is an in-place Cholesky factorization of a symmetric positive
 * definite matrix A, producing a lower-triangular factor L such that:
 *
 *   A (on entry) = SPD matrix
 *   A (on exit)  = L, where A = L * L^T
 *
 * Only the lower triangle of A is used/updated.
 *
 * Optimizations relative to the original version:
 *   - Use row pointers (Ai, Aj) to reduce address arithmetic.
 *   - Use local accumulation variables ("sum") in the inner dot products.
 *     This improves data locality and enables better vectorization.
 *   - Add OpenMP "simd" hints on the innermost loops to encourage
 *     auto-vectorization by the compiler.
 *
 * The algebra is unchanged; only the grouping of floating-point
 * operations differs slightly, which can lead to tiny rounding
 * differences but preserves the mathematical result.
 */
static
__attribute__((flatten, noinline))
void kernel_cholesky(int n,
                     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    /* Pointer to current row i of A for faster access. */
    DATA_TYPE *restrict Ai = A[i];

    /* Off-diagonal elements in row i (j < i). */
    for (j = 0; j < i; j++) {
      DATA_TYPE *restrict Aj = A[j];
      DATA_TYPE sum = (DATA_TYPE)0;

      /* Dot product: sum_{k=0}^{j-1} Ai[k] * Aj[k].
       * Equivalent to the original:
       *   for (k = 0; k < j; k++)
       *     A[i][j] -= A[i][k] * A[j][k];
       *   A[i][j] /= A[j][j];
       * but using a temporary accumulator reduces memory traffic and
       * exposes a clean reduction for SIMD. */
#pragma omp simd reduction(+:sum)
      for (k = 0; k < j; k++) {
        sum += Ai[k] * Aj[k];
      }

      Ai[j] = (Ai[j] - sum) / Aj[j];
    }

    /* Diagonal element in row i. */
    {
      DATA_TYPE sum = (DATA_TYPE)0;

      /* sum_{k=0}^{i-1} Ai[k]^2
       * Equivalent to the original:
       *   for (k = 0; k < i; k++)
       *     A[i][i] -= A[i][k] * A[i][k];
       *   A[i][i] = SQRT_FUN(A[i][i]);
       * but expressed as:
       *   A[i][i] = sqrt( A[i][i] - sum_{k} Ai[k]^2 ).
       */
#pragma omp simd reduction(+:sum)
      for (k = 0; k < i; k++) {
        DATA_TYPE aik = Ai[k];
        sum += aik * aik;
      }

      Ai[i] = SQRT_FUN(Ai[i] - sum);
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
