    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restricted view of the matrix to help the compiler with
   * alias analysis and enable better vectorization. */
  DATA_TYPE (* restrict A_)[n] = (DATA_TYPE (*)[n])A;

  /* Cache reciprocals of diagonal elements.
   * This replaces O(n^2) divisions in the inner loops with O(n^2)
   * multiplications and only O(n) divisions when the diagonal is
   * computed.  The extra memory is O(n), i.e., negligible compared
   * to the O(n^2) main matrix. */
  DATA_TYPE inv_diag[n];

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE * restrict Ai = A_[i];

    /* Off-diagonal elements in row i: j < i. */
    for (j = 0; j < i; j++) {
      DATA_TYPE * restrict Aj = A_[j];

      /* Compute inner product sum_{k < j} Ai[k] * Aj[k].
       *
       * Compared to the original implementation, we explicitly
       * accumulate in a temporary 'sum' instead of repeatedly
       * updating A[i][j]. This reduces memory traffic and enables
       * efficient SIMD vectorization. The mathematical result is
       * the same, up to standard floating-point round-off. */
      DATA_TYPE sum = (DATA_TYPE)0;

#pragma omp simd reduction(+:sum)
      for (k = 0; k < j; k++) {
        sum += Ai[k] * Aj[k];
      }

      /* A[i][j] = (A[i][j] - sum_{k<j} A[i][k] * A[j][k]) / A[j][j]; */
      Ai[j] = (Ai[j] - sum) * inv_diag[j];
    }

    /* Diagonal element (i == j).
     *
     * Original:
     *   for (k = 0; k < i; k++)
     *     A[i][i] -= A[i][k] * A[i][k];
     *   A[i][i] = SQRT_FUN(A[i][i]);
     *
     * Here we first compute sum_{k<i} A[i][k]^2 and then perform a
     * single subtraction and square root. This reduces memory
     * accesses and allows SIMD over k. */
    DATA_TYPE sum = (DATA_TYPE)0;

#pragma omp simd reduction(+:sum)
    for (k = 0; k < i; k++) {
      DATA_TYPE aik = Ai[k];
      sum += aik * aik;
    }

    DATA_TYPE diag = SQRT_FUN(Ai[i] - sum);
    Ai[i] = diag;

    /* Store 1 / A[i][i] for use in later rows (i' > i). */
    inv_diag[i] = (DATA_TYPE)1.0 / diag;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
