/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Original lower-triangular pattern initialization. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite:
     B = A * A^T, then copy B back into A.

     The original code:
       - Initialized B to zero,
       - Performed a triple loop with order (t, r, s),
       - Updated B[r][s] inside the innermost loop.

     Optimizations applied here:
       - Use r and s as the outer loops so that for each (r,s)
         we access A[r][:] and A[s][:] contiguously in memory,
         improving cache locality.
       - Use a local accumulator 'sum' and write B[r][s] only once,
         reducing memory traffic.
       - Parallelize the outer r-loop with OpenMP. Each thread works
         on independent rows of B, so no synchronization is required.
       - The accumulation order over t (0..n-1) for each (r,s) is
         preserved, so the floating-point computation semantics for
         each element B[r][s] remain the same.
  */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Compute B = A * A^T with improved locality and parallelism. */
#pragma omp parallel for private(s, t) schedule(static) if (n > 64)
  for (r = 0; r < n; ++r)
  {
    for (s = 0; s < n; ++s)
    {
      DATA_TYPE sum = (DATA_TYPE)0;
      for (t = 0; t < n; ++t)
      {
        sum += A[r][t] * A[s][t];
      }
      (POLYBENCH_ARRAY(B))[r][s] = sum;
    }
  }

  /* Copy B back into A. Kept as simple nested loops for clarity; the
     compiler can optimize this to an efficient memcpy-equivalent. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
    if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* The algorithm is a standard in-place Cholesky decomposition on the
     lower-triangular part of A.

     Optimizations applied:
       - Introduce row pointers (Ai, Aj) to avoid repeatedly computing
         A[i] and A[j] addresses and to improve cache locality.
       - Use local accumulators (sum, sum_diag) so that each element
         A[i][j] is kept in a register while its inner-product is
         accumulated, reducing loads/stores and allowing the compiler
         to better optimize the inner loops.
       - The order of arithmetic operations for each element is kept
         identical to the original code: we start from the original
         A[i][j] / A[i][i] value and subtract contributions for k
         in increasing order before the final division/square root.
  */

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     /* Pointer to the current row i, reused in inner loops. */
     DATA_TYPE * restrict Ai = A[i];

     /* Off-diagonal elements: j < i. */
     for (j = 0; j < i; j++) {
        DATA_TYPE * restrict Aj = A[j];

        /* Start from the original value A[i][j] and subtract the
           dot product of the first j-1 elements of rows i and j. */
        DATA_TYPE sum = Ai[j];
        for (k = 0; k < j; k++) {
           sum -= Ai[k] * Aj[k];
        }

        /* Final scaling by the diagonal term A[j][j]. */
        Ai[j] = sum / Aj[j];
     }

     /* Diagonal element: i == j.
        Start from A[i][i] and subtract the squared norm of the
        already computed elements in row i. */
     DATA_TYPE sum_diag = Ai[i];
     for (k = 0; k < i; k++) {
        sum_diag -= Ai[k] * Ai[k];
     }
     Ai[i] = SQRT_FUN(sum_diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

